// Fail closed: audienceCsv kommt ausschliesslich aus dem Parent-Kontext,
// niemals vom Modell. Unbekannte Werte werden verworfen, nicht durchgereicht.
const ERLAUBT = ['public', 'it_internal'];
const inp = $input.first().json ?? {};
const auds = String(inp.audienceCsv ?? '')
  .split(',').map(a => a.trim().toLowerCase())
  .filter(a => ERLAUBT.includes(a));
const uniq = [...new Set(auds)];
const suchtext = String(inp.suchtext ?? '').trim().slice(0, 800);
const topN = Math.min(Math.max(Number(inp.topN ?? 8) || 8, 1), 12);

// FIX 08/2026 (Beleg: Lauf 104948): Eine Vorgangskennung im Suchtext wurde
// bisher wie ein gewoehnliches Suchwort behandelt. Der strenge Volltextpfad
// verknuepft alle Begriffe mit UND - ein einziger Begriff ohne Entsprechung in
// der Wissensbasis setzt ihn zwingend auf null. Im Beleglauf war das "SZU",
// das in keinem einzigen Chunk vorkommt (verifiziert, 0 Treffer ueber alle
// Quellen). SSD-3512 lag mit 20 Chunks im Index und wurde trotzdem nicht
// gefunden. Die Kennung wird deshalb hier extrahiert und im SQL als direkter
// Lookup ohne Score-Bewertung ausgewertet.
// Bewusst tolerant gemustert: Ein Fehltreffer wie "COVID-19" trifft im SQL auf
// kein source_ref und liefert null Zeilen. Der Pfad kann nichts kaputtmachen,
// nur zusaetzlich finden.
const KENNUNG = /\b[A-Za-z]{2,10}-\d{1,6}\b/g;
const identKeys = [...new Set((suchtext.match(KENNUNG) || []).map(k => k.toUpperCase()))].slice(0, 5);

// FIX 08/2026 (Beleg: Lauf 104980): userEmail kommt wie audienceCsv aus dem
// Parent-Kontext, nie vom Modell. Sie dient ausschliesslich dem Abgleich mit
// Melder, Bearbeiter und Request-Teilnehmer eines Vorgangs - sie erweitert
// keinen Zugriff. Ohne gueltige Adresse bleibt die Zuordnung schlicht leer.
const roh = String(inp.userEmail ?? '').trim().toLowerCase();
const userEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(roh) ? roh.slice(0, 200) : '';

// Leere Liste => SQL liefert null Zeilen (verifiziert). Kein Bypass moeglich.
// Gleiches gilt fuer identCsv: leerer String => string_to_array liefert ein
// Array der Laenge 0 => die ident-CTE bleibt leer.
return [{ json: {
  suchtext,
  audienceCsv: uniq.join(','),
  identCsv: identKeys.join(','),
  identKeys,
  userEmail,
  topN,
  gueltig: uniq.length > 0 && suchtext.length > 1
} }];

const src = $('Wissen hybrid abrufen').first().json ?? {};
const cand = Array.isArray(src.candidates) ? src.candidates : [];
const ctl = $('Eingaben pruefen').first().json ?? {};
const resp = $input.first().json ?? {};
const results = Array.isArray(resp.results) ? resp.results : [];

// FIX 08/2026 (Beleg: Lauf 104948): Direkttreffer ueber die Vorgangskennung.
// Sie kommen aus einer eigenen SQL-CTE, laufen bewusst NICHT durch den
// Reranker und unterliegen keinem Score-Boden. Eine Kennung ist eine exakte
// Referenz, keine Aehnlichkeit - der Reranker wuerde sie an der Wortwahl der
// Frage messen und dabei zwangslaeufig verwerfen (im Beleglauf Bestwert
// 0.0825 gegen Boden 0.15, obwohl 20 Chunks zum Vorgang im Index lagen).
const identRoh = Array.isArray(src.identHits) ? src.identHits : [];
const identBilder = Number(src.identBilder ?? 0);
const identPfad = identRoh.length > 0;

// Cohere rerank-v3.5 liefert bei deutscher Fachdokumentation flache,
// unkalibrierte Scores. Absolute Schwellen taugen nur als Muellfilter;
// die fachliche Gewichtung macht der Agent anhand des Wertes.
const BODEN = 0.05;
// Im gelockerten Volltextpfad (ODER statt UND) landen zwangslaeufig Chunks im
// Pool, die nur ein einzelnes Allerweltswort teilen. Beleg Lauf 102613: auf
// eine AWS-Frage kamen Debitorencockpit-Seiten mit Bestwert 0.1014 durch.
// Deshalb muss sich der Rueckfall seine Treffer verdienen - sonst ist eine
// offene Absage die bessere Antwort als drei glaubwuerdige Fehltreffer.
const BODEN_RUECKFALL = 0.15;
const MAX_JE_QUELLE = 2;   // ein Dokument darf die Liste nicht dominieren
const MAX_BILDCHUNKS = 1;  // Bildbeschreibungen sind lang und verdraengen Doku

// Die Rolle steht in der angefragten Audience. Sie kommt aus dem
// Parent-Kontext und wurde in 'Eingaben pruefen' gegen die Whitelist geprueft.
const istITAnfrage = String(ctl.audienceCsv || '').split(',').map(a => a.trim()).includes('it_internal');

const lexStrikt = Number(src.lexStrikt ?? 0);
const lexOder = Number(src.lexOder ?? 0);
const lexRueckfall = lexStrikt === 0 && lexOder > 0;
const boden = lexRueckfall ? BODEN_RUECKFALL : BODEN;

let ranked;
if (results.length) {
  ranked = results
    .map(r => { const c = cand[Number(r.index)]; return c ? { ...c, score: Number(r.relevance_score ?? 0) } : null; })
    .filter(Boolean)
    .sort((a, b) => b.score - a.score);
} else {
  // Ohne Reranker-Antwort auf die RRF-Reihenfolge zurueckfallen, nicht leer liefern.
  ranked = cand.map(c => ({ ...c, score: null }));
}

// Liegt ein Direkttreffer vor, ist die Frage beantwortet. Die semantischen
// Kandidaten sind dann nur noch Beiwerk und duerfen den Vorgang nicht
// zutexten. Im gelockerten Volltextpfad entfallen sie ganz: dort ist der Pool
// per Konstruktion Rauschen, und Rauschen neben einem gesicherten Treffer ist
// schaedlicher als anderswo, weil es glaubwuerdig danebensteht.
const limit = identPfad
  ? (lexRueckfall ? 0 : 3)
  : (Number(ctl.topN) || 8);

const istBild = r => String(r.chunkType) === 'image_attachment';
const hatTextTreffer = ranked.some(r => !istBild(r) && (r.score === null || r.score >= boden));

const gewaehlt = [];
const jeQuelle = {};
let bildzahl = 0;

for (const r of ranked) {
  if (gewaehlt.length >= limit) break;
  if (r.score !== null && r.score < boden) continue;

  const ref = String(r.sourceRef || '?');
  if ((jeQuelle[ref] || 0) >= MAX_JE_QUELLE) continue;

  // Was der Identifier-Pfad schon geliefert hat, nicht doppelt ausgeben.
  if (identPfad && identRoh.some(i => String(i.sourceRef) === ref)) continue;

  if (istBild(r)) {
    if (bildzahl >= MAX_BILDCHUNKS) continue;
    // Kein Bildchunk auf Platz 1, solange echte Doku verfuegbar ist.
    if (gewaehlt.length === 0 && hatTextTreffer) continue;
    bildzahl++;
  }

  jeQuelle[ref] = (jeQuelle[ref] || 0) + 1;
  gewaehlt.push(r);
}

// ENTSCHEIDUNG 08/2026: Confluence-Links gehen an die IT, nicht an den
// Fachbereich. Wer den Inhalt sehen darf, darf auch wissen, wo er steht - die
// Audience-Pruefung hat den Zugriff bereits entschieden. Fuer alle anderen
// wird die URL entfernt, damit kein Verweis auf eine Seite entsteht, die sie
// nicht oeffnen koennen. Bewusst im Code statt im Systemprompt: der Agent gibt
// nur Links aus, die im Werkzeugergebnis stehen.
const istConfluence = r => String(r.sourceType) === 'confluence';
const linkUnterdruecken = r => istConfluence(r) && !istITAnfrage;

// Signaturbloecke ranken hoch, weil sie in fast jedem Ticket stehen, taugen
// aber nicht als Stammdatenquelle: In den Signaturen kommen mehrere
// verschiedene Dienstsitze vor (Siemensring 44 L, Anrather Str. 3-5, Zum
// Gueterbahnhof 1). Der Agent griff bisher einen davon heraus und antwortete
// glaubwuerdig falsch. Erkennen statt loeschen: der Chunk kann daneben
// echten Ticketinhalt enthalten.
const signaturMuster = [
  /Dienstsitz\s*\|/i,
  /Amtsgericht\s+Krefeld\s+GnR/i,
  /(viele|freundliche|mit freundlichen)\s+gr(ü|u)(ß|ss)e/i,
  /www\.rwg-r\.de/i
];
const istSignatur = r => signaturMuster.filter(m => m.test(String(r.text || ''))).length >= 2;
const signaturTreffer = gewaehlt.filter(istSignatur).length;

// Direkttreffer zuerst: sie sind die belastbare Auskunft, alles danach ist
// Kontext. 'relevanz' bleibt bewusst null - es gibt keinen Score, weil nicht
// gescort wurde. 'gesichert' sagt dem Agenten, worauf er sich stuetzen darf.
// FIX 08/2026 (Beleg: Lauf 104964): Die Sichtbarkeitsstufe fehlte im Treffer.
// Bei der Frage, was ein Anwender sehen darf, konnte der Agent interne von
// oeffentlichen Inhalten nur daran unterscheiden, dass im Chunktext zufaellig
// "| intern |" stand. Das hat funktioniert, war aber Zufall statt Mechanismus.
// Die Stufe steht ohnehin in der Zeile - sie gehoert ausgegeben.
const identTreffer = identRoh.map(r => ({
  titel: r.title,
  quelle: r.sourceType,
  referenz: r.sourceRef,
  art: r.chunkType,
  audience: r.audience,
  zuordnung: r.zuordnung ?? null,
  url: linkUnterdruecken(r) ? '' : (r.url || ''),
  relevanz: null,
  gesichert: true,
  text: String(r.text ?? '').slice(0, 1400)
}));

const semantischeTreffer = gewaehlt.map(r => ({
  titel: r.title,
  quelle: r.sourceType,
  referenz: r.sourceRef,
  art: r.chunkType,
  audience: r.audience,
  url: linkUnterdruecken(r) ? '' : (r.url || ''),
  relevanz: r.score === null ? null : Number(r.score.toFixed(4)),
  gesichert: false,
  text: String(r.text ?? '').slice(0, 1800)
}));

const treffer = [...identTreffer, ...semantischeTreffer];

const linksUnterdrueckt = identRoh.filter(linkUnterdruecken).length
  + gewaehlt.filter(linkUnterdruecken).length;

// Diagnose: belegt, welche Audiences ueberhaupt in den Kandidatenpool kamen.
const nachAudience = {};
for (const c of cand) { const a = String(c.audience || '?'); nachAudience[a] = (nachAudience[a] || 0) + 1; }
const identNachAudience = {};
for (const c of identRoh) { const a = String(c.audience || '?'); identNachAudience[a] = (identNachAudience[a] || 0) + 1; }

// Anweisung statt blosser Feststellung: im Werkzeugergebnis wirkt sie
// zuverlaessiger als eine Regel im Systemprompt (Beleg: Vollstaendigkeits-
// hinweis im Jira-Subflow). Bei null Treffern soll der Agent die Luecke offen
// benennen und nicht aus Allgemeinwissen weiterreden.
const hinweise = [];
if (!treffer.length) {
  if (ctl.identKeys && ctl.identKeys.length) {
    hinweise.push('Zu der genannten Kennung (' + ctl.identKeys.join(', ') + ') liegt in der Wissensbasis kein Vorgang vor, auf den diese Anfrage zugreifen darf. Sage das offen. Erfinde keinen Vorgang und rate keine Kennung.');
  } else {
    hinweise.push('Keine passenden Wissenstreffer fuer diese Anfrage. Sage offen, dass die interne Wissensbasis dazu nichts enthaelt. Beantworte die Frage nicht aus Allgemeinwissen und erfinde keine Quelle. Geht es um ein externes Thema ohne internen Bezug, nutze stattdessen die Web-Recherche.');
  }
} else {
  // FIX 08/2026 (Beleg: Lauf 104980): Zuordnung kommt jetzt belegt aus
  // jira_tickets mit. Als Anweisung im Werkzeugergebnis statt als Regel im
  // Systemprompt - dort hat die Vorgabe "erst Inhalt, dann Besitz" nicht
  // gegriffen, das Modell hat den Besitz stattdessen geraten.
  const zuordnungJeRef = {};
  for (const r of identRoh) { if (r.zuordnung) zuordnungJeRef[String(r.sourceRef)] = r.zuordnung; }
  const paare = Object.entries(zuordnungJeRef);
  const eigene = paare.filter(([, z]) => z === 'melder' || z === 'bearbeiter' || z === 'teilnehmer');
  const fremde = paare.filter(([, z]) => z === 'fremd');
  const unklar = paare.filter(([, z]) => z === 'unbekannt');
  if (eigene.length) {
    hinweise.push('Belegte Zuordnung: ' + eigene.map(([k, z]) => k + ' = ' + z).join(', ') + '. Die fragende Person ist dort beteiligt, du darfst den Vorgang als ihren bezeichnen.');
  }
  if (fremde.length) {
    hinweise.push('Belegte Zuordnung: ' + fremde.map(([k]) => k).join(', ') + ' ist der fragenden Person nicht zugeordnet. Formuliere neutral und behaupte nicht, es sei ihr Vorgang. Leite den Besitz nie aus dem Gespraechsverlauf ab.');
  }
  if (unklar.length) {
    hinweise.push('Zur Zuordnung von ' + unklar.map(([k]) => k).join(', ') + ' liegen keine Daten vor. Sage dazu nichts ueber den Besitz.');
  }
  if (identPfad) {
    hinweise.push('Die Treffer mit "gesichert": true stammen aus einem direkten Zugriff auf die genannte Vorgangskennung und sind vollstaendig fuer die angefragte Sichtbarkeit. Stuetze deine Antwort auf diese Treffer und werte sie aus, statt nur Titel und Status zu nennen. Kommentare stehen in zeitlicher Reihenfolge; der letzte gibt den aktuellen Stand wieder.');
    if (identBilder > 0) {
      hinweise.push('Zu dem Vorgang liegen ausserdem ' + identBilder + ' Bildanhaenge vor, die hier aus Platzgruenden nicht mitgeliefert wurden. Erwaehne, dass es sie gibt, und beschreibe ihren Inhalt nicht.');
    }
  }
  if (treffer.some(t => t.audience === 'it_internal')) {
    hinweise.push('Jeder Treffer traegt das Feld "audience". "public" heisst fuer Anwender sichtbar, "it_internal" heisst ausschliesslich intern fuer die IT. Unterscheidet die Frage danach, was Anwender sehen duerfen, stuetze diese Unterscheidung allein auf dieses Feld und nicht auf den Wortlaut des Textes. Gib interne Inhalte nicht als Anwendersicht aus.');
  }
  // FIX 08/2026 (Beleg: Lauf 104989, "drucker geht nicht"): Der Agent zaehlte
  // drei aehnliche Tickets auf und nannte nur deren Problembeschreibung,
  // obwohl in denselben Treffern die Loesung stand. Fuer den Anwender ist die
  // Ticketnummer wertlos, der Loesungsweg ist der Punkt.
  if (treffer.some(t => String(t.art) === 'solution')) {
    hinweise.push('Unter den Treffern stehen dokumentierte Loesungen (art: solution). Gib die Loesungsschritte konkret wieder, statt nur Ticketnummer und Problembeschreibung zu nennen.');
  }
  if (lexRueckfall && semantischeTreffer.length) {
    hinweise.push('Die Volltextsuche traf erst in der gelockerten Lesart. Pruefe die Treffer am Wortlaut der Frage, bevor du sie als Antwort nutzt, und nenne sie nicht als gesicherte Auskunft.');
  }
  if (signaturTreffer >= Math.ceil(treffer.length / 2)) {
    hinweise.push('Die Treffer stammen ueberwiegend aus E-Mail-Signaturen in Tickets. Signaturen sind als Quelle fuer Stammdaten wie Standort, Anschrift, Telefonnummer oder Zustaendigkeit unzuverlaessig, weil darin mehrere verschiedene Dienstsitze vorkommen. Stuetze darauf keine Aussage. Geht es um eine oeffentlich verfuegbare Angabe zur RWG, nutze stattdessen die Web-Recherche.');
  }
  if (linksUnterdrueckt > 0) {
    hinweise.push('Zu Confluence-Treffern liegt hier bewusst keine URL vor. Nenne den Titel der Seite als Quelle und verlinke sie nicht.');
  }
}

return [{ json: {
  trefferAnzahl: treffer.length,
  treffer,
  hinweis: hinweise.join(' '),
  diagnose: {
    kandidatenAnzahl: cand.length,
    rerankerAktiv: results.length > 0,
    kandidatenNachAudience: nachAudience,
    angefragteAudiences: ctl.audienceCsv,
    istITAnfrage,
    identPfad,
    identKeys: ctl.identKeys ?? [],
    identAnzahl: identRoh.length,
    identNachAudience,
    identBilderUnterdrueckt: identBilder,
    semantischeTreffer: semantischeTreffer.length,
    linksUnterdrueckt,
    verschiedeneQuellen: Object.keys(jeQuelle).length,
    bildchunks: bildzahl,
    signaturTreffer,
    lexStrikt,
    lexOder,
    lexRueckfall,
    bodenAngewandt: boden,
    bestScore: ranked.length && ranked[0].score !== null ? Number(ranked[0].score.toFixed(4)) : null
  }
} }];
